description:
.product-desc {
width: 100%;
max-width: none;
margin: 0;
padding: 18px;
box-sizing: border-box;
font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
color: #1f2937;
background: #ffffff;
border: 1px solid #eef0f4;
border-radius: 16px;
box-shadow: 0 8px 24px rgba(15, 23, 42, 0.05);
line-height: 1.7;
}
.product-desc * {
box-sizing: border-box;
}
.product-desc .title {
display: flex;
align-items: center;
gap: 12px;
margin-bottom: 14px;
}
.product-desc .logo {
width: 42px;
height: 42px;
border-radius: 12px;
background: #111827;
color: #ffffff;
display: flex;
align-items: center;
justify-content: center;
font-weight: 800;
font-size: 17px;
letter-spacing: 0.3px;
flex-shrink: 0;
}
.product-desc h2 {
margin: 0;
font-size: 22px;
font-weight: 800;
color: #111827;
}
.product-desc h2 span {
background: linear-gradient(135deg, #7c3aed, #a855f7);
-webkit-background-clip: text;
color: transparent;
}
.product-desc .sub {
margin: 4px 0 0;
font-size: 14px;
color: #6b7280;
}
.product-desc .card {
margin-top: 14px;
padding: 14px 16px;
background: #fafafa;
border: 1px solid #f0f0f0;
border-radius: 14px;
}
.product-desc .row {
display: flex;
gap: 10px;
padding: 8px 0;
font-size: 15px;
border-bottom: 1px solid #f1f1f1;
}
.product-desc .row:last-child {
border-bottom: none;
}
.product-desc .tag {
flex: 0 0 82px;
color: #7c3aed;
font-weight: 700;
}
.product-desc .text {
color: #374151;
flex: 1;
}
.product-desc .notice {
margin-top: 14px;
padding: 12px 14px;
background: #fff7ed;
border: 1px solid #fed7aa;
border-radius: 14px;
color: #9a3412;
font-size: 14px;
}
.product-desc .btn {
display: block;
width: 100%;
margin-top: 16px;
padding: 11px 18px;
border-radius: 12px;
background: linear-gradient(135deg, #7c3aed, #a855f7);
color: #ffffff;
text-align: center;
text-decoration: none;
font-size: 15px;
font-weight: 700;
box-shadow: 0 8px 18px rgba(124, 58, 237, 0.22);
}
@media (max-width: 520px) {
.product-desc {
padding: 15px;
border-radius: 14px;
}
.product-desc h2 {
font-size: 20px;
}
.product-desc .row {
display: block;
}
.product-desc .tag {
display: block;
margin-bottom: 2px;
}
}
